    + '<path class="srsi d" d="' + path(SD, yS) + '"/>'
    + '<text class="ax" x="' + (PADL - 8) + '" y="' + f(yS(100) + 3) + '" text-anchor="end">100</text>'
    + '<text class="ax" x="' + (PADL - 8) + '" y="' + f(yS(0) + 3) + '" text-anchor="end">0</text>'
